B.aT4=new A.iD('Bu kullan\u0131m ko\u015fullar\u0131, Koala by evlumba uygulamas\u0131n\u0131 ("Uygulama") kullan\u0131m\u0131n\u0131z\u0131 d\xfczenler. Uygulamay\u0131 kullanarak bu ko\u015fullar\u0131 kabul etmi\u015f say\u0131l\u0131rs\u0131n\u0131z.',null)
B.aT7=new A.iD("Son g\xfcncelleme: 18 Mart 2026",null)
B.aUx=new A.j2("Hizmet Tan\u0131m\u0131",null)
B.aT0=new A.iD("Koala, yapay zeka destekli bir mekan analiz uygulamas\u0131d\u0131r. Kullan\u0131c\u0131lar soru foto\u011fraf\u0131 \xe7ekerek ad\u0131m ad\u0131m \xe7\xf6z\xfcm alabilir. Uygulama 9 farkl\u0131 bran\u015fta AI destekli \xf6\u011fretim hizmeti sunar.",null)
B.aUt=new A.j2("Hesap ve Kay\u0131t",null)
B.aQt=new A.eH("Uygulamay\u0131 kullanmak i\xe7in Google veya telefon numaras\u0131 ile hesap olu\u015fturman\u0131z gerekir",null)
B.aQw=new A.eH("Hesap bilgilerinizin do\u011fru ve g\xfcncel olmas\u0131ndan siz sorumlusunuz",null)
B.aQf=new A.eH("Hesab\u0131n\u0131z\u0131n g\xfcvenli\u011finden siz sorumlusunuz",null)
B.aUC=new A.j2("Kredi Sistemi",null)
B.aQd=new A.eH("Her yeni kullan\u0131c\u0131ya 10 \xfccretsiz kredi verilir",null)
B.aQC=new A.eH("Her mekan analizi 1 kredi harcar",null)
B.aQB=new A.eH("Ek kredi uygulama i\xe7i sat\u0131n alma ile edinilebilir",null)
B.aQA=new A.eH("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aUu=new A.j2("Kabul Edilebilir Kullan\u0131m",null)
B.aSY=new A.iD("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
B.aQz=new A.eH("Uygulamay\u0131 k\xf6t\xfcye kullanmak veya ba\u015fkalar\u0131n\u0131n kullan\u0131m\u0131n\u0131 engellemek",null)
